import AppKit
import Games
import Strings

/// Draws games from `Assets/Games` (games.png + games.json, generated by
/// Tools/generate_sprites.py): the window frame, and each frame's scene into
/// a 160×120 image, 1 px per art pixel, scaled up by the window with
/// nearest-neighbour filtering. Exists only while a game window is open.
final class GameArt {
    let sheet: GameSheet
    private let atlas: CGImage
    private let text: BubbleRenderer
    private var crops: [String: CGImage] = [:]
    private var texts: [String: CGImage] = [:]
    private let context: CGContext

    init?(directory: URL, text: BubbleRenderer) {
        guard let data = try? Data(contentsOf: directory.appendingPathComponent("games.json")),
              let sheet = try? GameSheet(json: data),
              let image = NSImage(contentsOf: directory.appendingPathComponent("games.png"))?
                .cgImage(forProposedRect: nil, context: nil, hints: nil),
              let context = CGContext(data: nil, width: Playfield.width, height: Playfield.height, bitsPerComponent: 8,
                                      bytesPerRow: 0, space: CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB(),
                                      bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
        self.sheet = sheet
        atlas = image
        self.text = text
        self.context = context
        context.interpolationQuality = .none
    }

    var chromeSize: CGSize { CGSize(width: sheet.chrome.frame.w, height: sheet.chrome.frame.h) }

    /// The frame with the title and the close button (highlighted or not).
    func chrome(title: String, closeHighlighted: Bool) -> CGImage? {
        let c = sheet.chrome
        guard let frame = crop(c.frame, frame: 0),
              let ctx = CGContext(data: nil, width: c.frame.w, height: c.frame.h, bitsPerComponent: 8, bytesPerRow: 0,
                                  space: frame.colorSpace ?? CGColorSpaceCreateDeviceRGB(),
                                  bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
        ctx.interpolationQuality = .none
        let h = c.frame.h
        ctx.draw(frame, in: CGRect(x: 0, y: 0, width: c.frame.w, height: h))
        if let line = textImage(title) {
            ctx.draw(line, in: CGRect(x: c.titleX, y: h - c.titleY - line.height, width: line.width, height: line.height))
        }
        if let button = crop(c.close, frame: closeHighlighted ? 1 : 0) {
            ctx.draw(button, in: CGRect(x: c.closeX, y: h - c.closeY - c.close.h, width: c.close.w, height: c.close.h))
        }
        return ctx.makeImage()
    }

    /// One frame of a game: its scene plus the session's extras (best score,
    /// new best, paused).
    func render(_ session: GameSession, game id: String) -> CGImage? {
        let scene = session.scene
        let h = Playfield.height
        context.clear(CGRect(x: 0, y: 0, width: Playfield.width, height: h))
        if let name = scene.background, let item = sheet.item(game: id, name: name), let image = crop(item, frame: 0) {
            context.draw(image, in: CGRect(x: 0, y: h - item.h, width: item.w, height: item.h))
        }
        for sprite in scene.sprites {
            guard let item = sheet.item(game: id, name: sprite.name), let image = crop(item, frame: sprite.frame) else { continue }
            context.draw(image, in: CGRect(x: sprite.x, y: h - sprite.y - item.h, width: item.w, height: item.h))
        }
        var lines = scene.texts.map { (Self.string(for: $0.key), $0) }
        lines.append((Strings.Games.best(session.best), GameText(.best(session.best), x: Playfield.width - 4, y: 3, align: .right)))
        if session.isNewBest && session.game.phase == .over {
            lines.append((Strings.Games.newBest, GameText(.newBest, x: Playfield.width / 2, y: 24, align: .center)))
        }
        if session.isPaused {
            lines = lines.filter { $0.1.y < 14 }  // keep the score line, drop the rest
            lines.append((Strings.Games.paused, GameText(.clickToPlay, x: Playfield.width / 2, y: 44, align: .center)))
        }
        for (string, placement) in lines {
            guard let line = textImage(string) else { continue }
            let x: Int
            switch placement.align {
            case .left: x = placement.x
            case .center: x = placement.x - line.width / 2
            case .right: x = placement.x - line.width
            }
            context.draw(line, in: CGRect(x: x, y: h - placement.y - line.height, width: line.width, height: line.height))
        }
        return context.makeImage()
    }

    static func string(for key: GameText.Key) -> String {
        switch key {
        case .clickToPlay: return Strings.Games.clickToPlay
        case .escToClose: return Strings.Games.escToClose
        case .newBest: return Strings.Games.newBest
        case .score(let value): return Strings.Games.score(value)
        case .best(let value): return Strings.Games.best(value)
        }
    }

    private func crop(_ item: GameSheet.Item, frame: Int) -> CGImage? {
        let origin = item.frame(frame)
        let key = "\(origin.x),\(origin.y),\(item.w),\(item.h)"
        if let cached = crops[key] { return cached }
        let image = atlas.cropping(to: CGRect(x: origin.x, y: origin.y, width: item.w, height: item.h))
        crops[key] = image
        return image
    }

    /// Pixel text, cached (scores change, so keep the cache small).
    private func textImage(_ string: String) -> CGImage? {
        if let cached = texts[string] { return cached }
        if texts.count > 64 { texts.removeAll() }
        let image = text.textImage(string)
        texts[string] = image
        return image
    }
}
